// SetInnerPhys sets Inner from a physical value: (p − offset) / factor, rounded half to even. It fails with ErrRange when the value is outside the signal's range or does not fit its 4 bits.
func (m *ExtMux) SetInnerPhys(p float64) error {
	if p < 0.0 || p > 15.0 {
		return fmt.Errorf("%w: ExtMux.Inner: %v", ErrRange, p)
	}
	x := (p - 0.0) / 1.0
	r := math.RoundToEven(x)
	if r < 0 || r > 15.0 {
		return fmt.Errorf("%w: ExtMux.Inner: %v", ErrRange, p)
	}
	m.Inner = uint8(r)
	return nil
}

// DeepPhys returns the physical value of Deep.
func (m *ExtMux) DeepPhys() float64 { return float64(m.Deep)*1.0 + 0.0 }

// SetDeepPhys sets Deep from a physical value: (p − offset) / factor, rounded half to even. It fails with ErrRange when the value is outside the signal's range or does not fit its 8 bits.
func (m *ExtMux) SetDeepPhys(p float64) error {
	if p < 0.0 || p > 255.0 {
		return fmt.Errorf("%w: ExtMux.Deep: %v", ErrRange, p)
	}
	x := (p - 0.0) / 1.0
	r := math.RoundToEven(x)
	if r < 0 || r > 255.0 {
		return fmt.Errorf("%w: ExtMux.Deep: %v", ErrRange, p)
	}
	m.Deep = uint8(r)
	return nil
}

// OtherPhys returns the physical value of Other.
func (m *ExtMux) OtherPhys() float64 { return float64(m.Other)*1.0 + 0.0 }

// SetOtherPhys sets Other from a physical value: (p − offset) / factor, rounded half to even. It fails with ErrRange when the value is outside the signal's range or does not fit its 16 bits.
func (m *ExtMux) SetOtherPhys(p float64) error {
	if p < 0.0 || p > 65535.0 {
		return fmt.Errorf("%w: ExtMux.Other: %v", ErrRange, p)
	}
	x := (p - 0.0) / 1.0
	r := math.RoundToEven(x)
	if r < 0 || r > 65535.0 {
		return fmt.Errorf("%w: ExtMux.Other: %v", ErrRange, p)
	}
	m.Other = uint16(r)
	return nil
}

// Encode returns the payload (8 bytes). Signals the multiplexers do not select are not written; their bits stay 0.
func (m *ExtMux) Encode() ([]byte, error) {
	data := make([]byte, 8)
	if !bits.FitsUnsigned(uint64(m.Outer), 4) {
		return nil, fmt.Errorf("%w: ExtMux.Outer: %d", ErrRange, m.Outer)
	}
	bits.InsertLE(data, 0, 4, uint64(m.Outer))
	if uint64(m.Outer) == 1 {
		if !bits.FitsUnsigned(uint64(m.Inner), 4) {
			return nil, fmt.Errorf("%w: ExtMux.Inner: %d", ErrRange, m.Inner)
		}
		bits.InsertLE(data, 4, 4, uint64(m.Inner))
	}
	if (uint64(m.Outer) == 1) && (uint64(m.Inner) == 2 || (uint64(m.Inner) >= 5 && uint64(m.Inner) <= 6)) {
		bits.InsertLE(data, 8, 8, uint64(m.Deep))
	}
	if (uint64(m.Outer) == 1) && (uint64(m.Inner) >= 3 && uint64(m.Inner) <= 4) {
		bits.InsertLE(data, 8, 16, uint64(m.Other))
	}
	return data, nil
}

// Decode sets the fields from a payload of at least 8 bytes. Signals the multiplexers do not select are set to zero.
func (m *ExtMux) Decode(data []byte) error {
	if len(data) < 8 {
		return fmt.Errorf("%w: ExtMux needs 8 bytes, got %d", ErrLength, len(data))
	}
	*m = ExtMux{}
	m.Outer = uint8(bits.ExtractLE(data, 0, 4))
	if uint64(m.Outer) == 1 {
		m.Inner = uint8(bits.ExtractLE(data, 4, 4))
	}
	if (uint64(m.Outer) == 1) && (uint64(m.Inner) == 2 || (uint64(m.Inner) >= 5 && uint64(m.Inner) <= 6)) {
		m.Deep = uint8(bits.ExtractLE(data, 8, 8))
	}
	if (uint64(m.Outer) == 1) && (uint64(m.Inner) >= 3 && uint64(m.Inner) <= 4) {
		m.Other = uint16(bits.ExtractLE(data, 8, 16))
	}
	return nil
}

// Frame encodes the message into a frame.
func (m *ExtMux) Frame() (canbus.Frame, error) {
	data, err := m.Encode()
	if err != nil {
		return canbus.Frame{}, err
	}
	return canbus.NewStandard(ExtMuxID, data)
}

// FdMsgID is the identifier of FdMsg (29-bit).
const FdMsgID canbus.ID = 0x200

// FdMsgLength is the payload length of FdMsg in bytes.
const FdMsgLength = 64

// FdMsg is the message FdMsg.
//
// Identifier 0x200 (extended), 64 bytes, CAN FD with bit rate switching, sent by ECU1.
//
// Fields hold raw values; the Phys methods scale them.
type FdMsg struct {
	// First: 8 bit little_endian unsigned at start bit 0; physical = raw × 1.0 + 0.0, range 0.0..255.0.
	First uint8
	// Last: 8 bit big_endian unsigned at start bit 511; physical = raw × 1.0 + 0.0, range 0.0..255.0.
	Last uint8
}

// MessageID returns FdMsgID.
func (*FdMsg) MessageID() canbus.ID { return FdMsgID }

// MessageName returns "FdMsg".
func (*FdMsg) MessageName() string { return "FdMsg" }

// FirstPhys returns the physical value of First.
func (m *FdMsg) FirstPhys() float64 { return float64(m.First)*1.0 + 0.0 }

// SetFirstPhys sets First from a physical value: (p − offset) / factor, rounded half to even. It fails with ErrRange when the value is outside the signal's range or does not fit its 8 bits.
func (m *FdMsg) SetFirstPhys(p float64) error {
	if p < 0.0 || p > 255.0 {
		return fmt.Errorf("%w: FdMsg.First: %v", ErrRange, p)
	}
	x := (p - 0.0) / 1.0
	r := math.RoundToEven(x)
	if r < 0 || r > 255.0 {
		return fmt.Errorf("%w: FdMsg.First: %v", ErrRange, p)
	}
	m.First = uint8(r)
	return nil
}

// LastPhys returns the physical value of Last.
func (m *FdMsg) LastPhys() float64 { return float64(m.Last)*1.0 + 0.0 }

// SetLastPhys sets Last from a physical value: (p − offset) / factor, rounded half to even. It fails with ErrRange when the value is outside the signal's range or does not fit its 8 bits.
func (m *FdMsg) SetLastPhys(p float64) error {
	if p < 0.0 || p > 255.0 {
		return fmt.Errorf("%w: FdMsg.Last: %v", ErrRange, p)
	}
	x := (p - 0.0) / 1.0
	r := math.RoundToEven(x)
	if r < 0 || r > 255.0 {
		return fmt.Errorf("%w: FdMsg.Last: %v", ErrRange, p)
	}
	m.Last = uint8(r)
	return nil
}

// Encode returns the payload (64 bytes). Signals the multiplexers do not select are not written; their bits stay 0.
func (m *FdMsg) Encode() ([]byte, error) {
	data := make([]byte, 64)
	bits.InsertLE(data, 0, 8, uint64(m.First))
	bits.InsertBE(data, 504, 8, uint64(m.Last))
	return data, nil
}

// Decode sets the fields from a payload of at least 64 bytes. Signals the multiplexers do not select are set to zero.
func (m *FdMsg) Decode(data []byte) error {
	if len(data) < 64 {
		return fmt.Errorf("%w: FdMsg needs 64 bytes, got %d", ErrLength, len(data))
	}
	*m = FdMsg{}
	m.First = uint8(bits.ExtractLE(data, 0, 8))
	m.Last = uint8(bits.ExtractBE(data, 504, 8))
	return nil
}

// Frame encodes the message into a frame.
func (m *FdMsg) Frame() (canbus.Frame, error) {
	data, err := m.Encode()
	if err != nil {
		return canbus.Frame{}, err
	}
	return canbus.NewFD(FdMsgID, true, true, data)
}

func b2u(b bool) uint64 {
	if b {
		return 1
	}
	return 0
}

// New returns an empty message of the given identifier, or nil.
func New(id canbus.ID, extended bool) Message {
	switch {
	case id == EngineID && extended == false:
		return &Engine{}
	case id == SignedBEID && extended == false:
		return &SignedBE{}
	case id == FloatsID && extended == false:
		return &Floats{}
	case id == MuxedID && extended == false:
		return &Muxed{}
	case id == ExtMuxID && extended == false:
		return &ExtMux{}
	case id == FdMsgID && extended == true:
		return &FdMsg{}
	case id == WideID && extended == true:
		return &Wide{}
	}
	return nil
}

// Decode decodes a frame into the message of its identifier.
func Decode(f *canbus.Frame) (Message, error) {
	m := New(f.ID, f.IsExtended())
	if m == nil || f.IsRemote() || f.IsError() {
		return nil, fmt.Errorf("%w: %s", ErrUnknownMessage, f.String())
	}
	if err := m.Decode(f.Payload()); err != nil {
		return nil, err
	}
	return m, nil
}
